+        // Ensure all UUIDs are unique, even after the clock resets.
+        assertEquals(5_000, beforeReset.size());
+        assertEquals(5_000, afterReset.size());
+        beforeReset.addAll(afterReset);
+        assertEquals(10_000, beforeReset.size());
+    }
