+                for (int j = 0; j < vectors[i].length; j++) {
+                    assertTrue(iterator.hasNext());
+                    assertArrayEquals(vectors[i][j], iterator.next(), 0.0001f);
+                    assertEquals(expectedMagnitudes[i][j], magnitudes[j], 0.0001f);
+                }
+            }
+        }
+    }
